<script lang="ts">import {onMount,getContext} from 'svelte';import type {I18nState} from '../../../../../lib/i18n/i18n.svelte';import {createPosActivityState} from '../state/posActivityState.svelte';const i18n=getContext<I18nState>('i18n');const vm=createPosActivityState();onMount(()=>{void vm.load();});function change<K extends keyof typeof vm.query>(k:K,v:(typeof vm.query)[K]){vm.set(k,v);void vm.load();}function money(c:number){return new Intl.NumberFormat(undefined,{style:'currency',currency:'USD'}).format(c/100);}</script>
<section class="page"><header><div><p class="eyebrow">ABELLIS · SMART WMS</p><h1>{i18n.t('Actividad POS')}</h1><p>{i18n.t('Resumen de ventas, reembolsos, terminales y transacciones del punto de venta.')}</p></div><button onclick={()=>void vm.load()}>{i18n.t('Actualizar')}</button></header>
<div class="filters"><label>{i18n.t('Fecha')}<input type="date" value={vm.query.date??''} onchange={e=>change('date',e.currentTarget.value)}/></label><label>{i18n.t('Tipo de documento')}<select value={vm.query.orderType??'sale'} onchange={e=>change('orderType',e.currentTarget.value as 'sale'|'refund'|'all')}><option value="sale">{i18n.t('Ventas')}</option><option value="refund">{i18n.t('Reembolsos')}</option><option value="all">{i18n.t('Todos')}</option></select></label><label>{i18n.t('Canal')}<select value={vm.query.channel??''} onchange={e=>change('channel',(e.currentTarget.value||null) as 'counter'|'phone'|null)}><option value="">{i18n.t('Todos')}</option><option value="counter">{i18n.t('Mostrador')}</option><option value="phone">{i18n.t('Teléfono')}</option></select></label><label>{i18n.t('Estado')}<select value={vm.query.status??''} onchange={e=>change('status',e.currentTarget.value||null)}><option value="">{i18n.t('Todos')}</option>{#each ['OPEN','ALLOCATED','PICKED','PACKED','SHIPPED','CANCELLED'] as s}<option value={s}>{s}</option>{/each}</select></label><label>{i18n.t('Terminal')}<input value={vm.query.terminalId??''} oninput={e=>vm.set('terminalId',e.currentTarget.value||null)} onkeydown={e=>{if(e.key==='Enter')void vm.load();}}/></label></div>
{#if vm.error}<p class="error" role="alert">{vm.error}</p>{/if}{#if vm.summary}<div class="kpis"><article><span>{i18n.t('Ventas')}</span><strong>{vm.summary.salesCount}</strong><small>{money(vm.summary.salesTotalCents)}</small></article><article><span>{i18n.t('Reembolsos')}</span><strong>{vm.summary.refundCount}</strong><small>{money(vm.summary.refundTotalCents)}</small></article><article><span>{i18n.t('Ingresos netos')}</span><strong>{money(vm.summary.netCents)}</strong></article><article><span>{i18n.t('Promedio por venta')}</span><strong>{money(vm.summary.averageSaleCents)}</strong></article><article><span>{i18n.t('Terminales activos')}</span><strong>{vm.summary.counterCount+vm.summary.phoneCount}</strong><small>{(vm.summary.counterCount+vm.summary.phoneCount)} {i18n.t('transacciones')}</small></article></div>{/if}
{#if vm.loading}<p>{i18n.t('Cargando…')}</p>{:else if vm.page.salesOrders.length===0}<p class="empty">{i18n.t('No hay transacciones para los filtros seleccionados.')}</p>{:else}<div class="table-wrap"><table><thead><tr><th>{i18n.t('Pedido')}</th><th>{i18n.t('Fecha')}</th><th>{i18n.t('Tipo')}</th><th>{i18n.t('Canal')}</th><th>{i18n.t('Estado')}</th><th>{i18n.t('Terminal')}</th><th>{i18n.t('Cliente')}</th><th>{i18n.t('Total')}</th><th>{i18n.t('Pago')}</th><th>{i18n.t('Referencia')}</th></tr></thead><tbody>{#each vm.page.salesOrders as r (r.salesOrderId)}<tr><td>{r.salesOrderNumber}</td><td>{r.createdAt??'—'}</td><td>{r.orderType}</td><td>{r.channel}</td><td>{r.status}</td><td>{r.terminalId??'—'}</td><td>{r.customerName??'—'}</td><td>{money(r.totalCents)}</td><td>{r.paymentMethod??'—'}</td><td>{r.externalTxnRef??'—'}</td></tr>{/each}</tbody></table></div><div class="pagination"><span>{vm.page.total} {i18n.t('registros')} · {i18n.t('Página')} {vm.page.page} / {vm.page.pages}</span><button disabled={vm.page.page<=1} onclick={()=>{vm.setPage(vm.page.page-1);void vm.load();}}>{i18n.t('Anterior')}</button><button disabled={vm.page.page>=vm.page.pages} onclick={()=>{vm.setPage(vm.page.page+1);void vm.load();}}>{i18n.t('Siguiente')}</button></div>{/if}</section>
<style>.page{max-width:78rem;margin:1.4rem auto;padding:0 1.1rem;color:var(--ink)}header{display:flex;justify-content:space-between;align-items:center;gap:1rem;margin-bottom:1rem}h1{margin:0;font:700 1.6rem var(--disp)}header p{color:var(--slate);font-size:.9rem}.eyebrow{font:600 .65rem var(--disp);letter-spacing:.14em}button{border:1px solid var(--line);border-radius:8px;padding:.5rem .7rem;background:var(--card);color:var(--ink);cursor:pointer}button:disabled{opacity:.45}.filters{display:flex;flex-wrap:wrap;gap:.7rem;margin:1rem 0}.filters label{display:grid;gap:.3rem;color:var(--slate);font-size:.78rem}.filters input,.filters select{min-height:38px;border:1px solid var(--line);border-radius:8px;padding:.45rem .6rem;background:var(--card);color:var(--ink)}.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:.7rem;margin:1rem 0}.kpis article{display:grid;gap:.25rem;padding:.9rem;border:1px solid var(--line);border-radius:10px;background:var(--card)}.kpis span,.kpis small{color:var(--slate);font-size:.75rem}.kpis strong{font:700 1.15rem var(--disp)}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:12px;background:var(--card)}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:.8rem}th,td{text-align:left;padding:.65rem;border-bottom:1px solid var(--line)}th{color:var(--slate);font-size:.68rem;text-transform:uppercase}.pagination{display:flex;justify-content:space-between;align-items:center;gap:.5rem;margin:1rem 0}.pagination span,.empty{color:var(--slate);font-size:.82rem}.error{color:var(--danger)}@media(max-width:640px){header{align-items:flex-start;flex-direction:column}.pagination{flex-wrap:wrap}}</style>